// LUCXI storefront demo. Products/cart/wishlist are stored in this browser's localStorage.
// For a public production shop, use a backend and secure admin authentication.
const ADMIN_PASSWORD = "CHANGE_ME_123"; // Replace this demo password before use.
const starterProducts = [
 {id:1,name:"Relaxed Graphic Tee",category:"Men",price:899,old:1299,image:"https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?auto=format&fit=crop&w=800&q=85",description:"Relaxed everyday premium T-shirt."},
 {id:2,name:"Minimal Everyday Shirt",category:"Men",price:1499,old:1999,image:"https://images.unsplash.com/photo-1596755389378-c31d21fd1273?auto=format&fit=crop&w=800&q=85",description:"Clean lines and an easy fit."},
 {id:3,name:"Neutral Fashion Outfit",category:"Women",price:1799,old:2499,image:"https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=800&q=85",description:"Modern neutral fashion outfit."},
 {id:4,name:"Classic Street Sneakers",category:"Shoes",price:2199,old:2999,image:"https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=800&q=85",description:"Street sneakers for daily wear."},
 {id:5,name:"Daily Carry Bag",category:"Accessories",price:999,old:1499,image:"https://images.unsplash.com/photo-1548036328-c9fa89d128fa?auto=format&fit=crop&w=800&q=85",description:"Carry your daily essentials."},
 {id:6,name:"Oversized T-Shirt",category:"Women",price:799,old:1199,image:"https://images.unsplash.com/photo-1503342217505-b0a15ec3261c?auto=format&fit=crop&w=800&q=85",description:"Oversized everyday comfort."}
];
let products = JSON.parse(localStorage.getItem("lucxi_products") || "null") || starterProducts;
let cart = JSON.parse(localStorage.getItem("lucxi_cart") || "[]");
let wishlist = JSON.parse(localStorage.getItem("lucxi_wishlist") || "[]");
let currentCategory = "All", selectedProduct = null, selectedSize = "M", editingId = null;
const content = document.getElementById("content");
const money = n => "₹" + Number(n || 0).toLocaleString("en-IN");
const escapeHTML = value => String(value ?? "").replace(/[&<>"']/g, ch => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
function saveProducts(){localStorage.setItem("lucxi_products",JSON.stringify(products));}
function enterStore(){document.getElementById("intro").classList.add("hidden");document.getElementById("store").classList.remove("hidden");goHome();}
function goHome(){currentCategory="All";renderHome();}
function showCategory(category){currentCategory=category;renderHome();}
function showPage(page){if(page==="wishlist")renderWishlist();else if(page==="cart")renderCart();else if(page==="admin")renderAdmin();}
function imgHTML(p){return `<img src="${escapeHTML(p.image)}" alt="${escapeHTML(p.name)}" loading="lazy" onerror="this.onerror=null;this.src='https://placehold.co/600x800?text=LUCXI'">`;}
function productCard(p){const liked=wishlist.includes(p.id);return `<article class="product-card"><button class="heart-btn" aria-label="Toggle wishlist" onclick="event.stopPropagation();toggleWish(${p.id})">${liked?"♥":"♡"}</button><div class="product-image" onclick="openProduct(${p.id})">${imgHTML(p)}</div><div class="product-info" onclick="openProduct(${p.id})"><h3>${escapeHTML(p.name)}</h3><p>${escapeHTML(p.category)}</p><span class="price">${money(p.price)}</span>${p.old?`<span class="old-price">${money(p.old)}</span>`:""}</div></article>`;}
function renderHome(){const q=(document.getElementById("search")?.value||"").toLowerCase();const list=products.filter(p=>(currentCategory==="All"||p.category===currentCategory)&&(`${p.name} ${p.category}`.toLowerCase().includes(q)));content.innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">THE NEW SEASON / 2026</span><h1>FIND YOUR<br>OWN STYLE.</h1><p>Fresh fits. Everyday essentials. Pieces that feel like you.</p><button class="primary-btn" onclick="showCategory('All')">SHOP COLLECTION ↗</button></div><div class="hero-graphic">✳</div></section><section class="section"><div class="section-heading"><h2>SHOP BY CATEGORY</h2><span>EXPLORE LUCXI</span></div><div class="categories">${["Men","Women","Shoes","Accessories"].map(c=>`<button class="category-tile" onclick="showCategory('${c}')">${c.toUpperCase()} ↗</button>`).join("")}</div><div class="section-heading"><h2>${currentCategory==="All"?"TRENDING NOW":currentCategory.toUpperCase()}</h2><span>${list.length} ITEMS</span></div><div class="product-grid">${list.map(productCard).join("")||`<div class="empty-state">No products found.</div>`}</div></section>`;}
function openProduct(id){selectedProduct=products.find(p=>p.id===id);selectedSize="M";if(selectedProduct)renderDetail(selectedProduct);}
function renderDetail(p){content.innerHTML=`<section class="product-detail"><div class="detail-image">${imgHTML(p)}</div><div class="detail-info"><p class="eyebrow">${escapeHTML(p.category)} / LUCXI EDIT</p><h1>${escapeHTML(p.name)}</h1><p><strong>${money(p.price)}</strong>${p.old?` <span class="old-price">${money(p.old)}</span>`:""}</p><p>${escapeHTML(p.description||"A versatile LUCXI fashion piece.")}</p><h4>SELECT SIZE</h4><div class="size-options">${["S","M","L","XL"].map(s=>`<button class="${selectedSize===s?"selected":""}" onclick="chooseSize('${s}')">${s}</button>`).join("")}</div><button class="primary-btn" onclick="addCart(${p.id})">ADD TO BAG</button><button class="secondary-btn" onclick="toggleWish(${p.id})">♡ WISHLIST</button><br><button class="secondary-btn" onclick="goHome()">← BACK TO SHOP</button></div></section>`;}
function chooseSize(size){selectedSize=size;renderDetail(selectedProduct);}
function addCart(id){cart.push({id,size:selectedSize});localStorage.setItem("lucxi_cart",JSON.stringify(cart));updateBag();toast("Added to bag!");}
function updateBag(){document.getElementById("bag-count").textContent=cart.length;}
function renderCart(){const rows=cart.map((item,i)=>{const p=products.find(x=>x.id===item.id);if(!p)return "";return `<div class="cart-row"><div><b>${escapeHTML(p.name)}</b><div>Size ${escapeHTML(item.size)} · ${money(p.price)}</div></div><button class="secondary-btn" onclick="removeCart(${i})">Remove</button></div>`;}).join("");const total=cart.reduce((sum,item)=>sum+(products.find(p=>p.id===item.id)?.price||0),0);content.innerHTML=`<section class="section"><h2>YOUR BAG (${cart.length})</h2>${rows||`<div class="empty-state">Your bag is empty.</div>`}<h3>Total: ${money(total)}</h3><button class="primary-btn" onclick="toast('Checkout demo — payments are not connected')">CHECKOUT</button><button class="secondary-btn" onclick="goHome()">SHOP MORE</button></section>`;}
function removeCart(index){cart.splice(index,1);localStorage.setItem("lucxi_cart",JSON.stringify(cart));updateBag();renderCart();}
function toggleWish(id){wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];localStorage.setItem("lucxi_wishlist",JSON.stringify(wishlist));if(selectedProduct)renderDetail(selectedProduct);else renderHome();}
function renderWishlist(){const list=products.filter(p=>wishlist.includes(p.id));content.innerHTML=`<section class="section"><h2>YOUR WISHLIST</h2><div class="product-grid">${list.map(productCard).join("")||`<div class="empty-state">Your wishlist is empty.</div>`}</div><button class="secondary-btn" onclick="goHome()">CONTINUE SHOPPING</button></section>`;}
function renderAdmin(){content.innerHTML=`<section class="admin-container"><div class="admin-panel"><h2>ADMIN DASHBOARD</h2><div id="admin-login" class="admin-login"><p>Admin access required.</p><input id="admin-pass" type="password" placeholder="Admin password"><button class="primary-btn" onclick="loginAdmin()">LOGIN</button></div><div id="admin-editor" class="hidden"><h3 id="form-heading">Add New Product</h3><div class="form-grid"><input id="p-name" placeholder="Product name"><select id="p-cat"><option>Men</option><option>Women</option><option>Shoes</option><option>Accessories</option></select><input id="p-price" type="number" min="1" placeholder="Price ₹"><input id="p-old" type="number" min="0" placeholder="Old price / MRP"><input id="p-image" class="full-width" placeholder="Product image URL"><textarea id="p-desc" class="full-width" placeholder="Product description"></textarea><button class="primary-btn full-width" onclick="saveProduct()">SAVE PRODUCT</button><button class="secondary-btn full-width" onclick="cancelEdit()">CANCEL / CLEAR</button></div><h3>Products (${products.length})</h3>${products.map(p=>`<div class="admin-product-row"><div><b>${escapeHTML(p.name)}</b><div>${escapeHTML(p.category)} · ${money(p.price)}</div></div><div><button onclick="editProduct(${p.id})">Edit</button><button onclick="deleteProduct(${p.id})">Delete</button></div></div>`).join("")}<button class="secondary-btn" onclick="logoutAdmin()">LOG OUT</button></div></div></section>`;}
function loginAdmin(){if(document.getElementById("admin-pass").value===ADMIN_PASSWORD){document.getElementById("admin-login").classList.add("hidden");document.getElementById("admin-editor").classList.remove("hidden");}else toast("Incorrect password");}
function logoutAdmin(){renderAdmin();}
function saveProduct(){const name=document.getElementById("p-name").value.trim(),category=document.getElementById("p-cat").value,price=Number(document.getElementById("p-price").value),old=Number(document.getElementById("p-old").value)||0,image=document.getElementById("p-image").value.trim(),description=document.getElementById("p-desc").value.trim();if(!name||price<=0||!image){toast("Please enter product name, valid price and image URL");return;}if(editingId){const product=products.find(x=>x.id===editingId);if(product)Object.assign(product,{name,category,price,old,image,description});}else products.unshift({id:Date.now(),name,category,price,old,image,description});saveProducts();editingId=null;renderAdmin();document.getElementById("admin-login").classList.add("hidden");document.getElementById("admin-editor").classList.remove("hidden");toast("Product saved!");}
function editProduct(id){const p=products.find(x=>x.id===id);if(!p)return;editingId=id;document.getElementById("p-name").value=p.name;document.getElementById("p-cat").value=p.category;document.getElementById("p-price").value=p.price;document.getElementById("p-old").value=p.old||"";document.getElementById("p-image").value=p.image;document.getElementById("p-desc").value=p.description||"";document.getElementById("form-heading").textContent="Edit Product";window.scrollTo({top:0,behavior:"smooth"});}
function cancelEdit(){editingId=null;["p-name","p-price","p-old","p-image","p-desc"].forEach(id=>{const el=document.getElementById(id);if(el)el.value="";});const heading=document.getElementById("form-heading");if(heading)heading.textContent="Add New Product";}
function deleteProduct(id){if(confirm("Delete this product?")){products=products.filter(p=>p.id!==id);saveProducts();renderAdmin();document.getElementById("admin-login").classList.add("hidden");document.getElementById("admin-editor").classList.remove("hidden");}}
let toastTimer;function toast(message){const el=document.getElementById("toast");el.textContent=message;el.classList.remove("hidden");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add("hidden"),2300);}
updateBag();
